using DG.Tweening;using UnityEngine;namespace FutureCore{    public abstract class DoTweenSequence:Base_CurveTween    {        protected Sequence sequence;        public DoTweenSequence()        {            CreadSequence();        }        private void CreadSequence()        {            // ����һ����������            sequence = DOTween.Sequence();            //sequence.SetAutoKill(false).SetRecyclable(true);             sequence.SetAutoKill(false);            AddTweenToSequence(sequence);            // ========== ��һ�׶Σ�˳�򶯻� ==========            // 1. ���ƶ���λ��A            //// 2. Ȼ����ת90��            //sequence.Append(target.DORotate(new Vector3(0, 90, 0), duration));            //// ========== �ڶ��׶Σ�ͬʱ���ŵĶ��� ==========            //// 3. �ƶ���λ��B��ͬʱ�ı���ɫ��������Renderer��            //sequence.Append(target.DOMove(new Vector3(2, 2, 0), duration));            ////sequence.Join(GetComponent<Renderer>().material.DOColor(Color.red, duration));            //// 4. Ȼ�����ź���תͬʱ����            //sequence.Append(target.DOScale(Vector3.one * 2, duration));            //sequence.Join(target.DORotate(new Vector3(0, 180, 0), duration));            // �������ʱ�ص�            sequence.OnComplete(OnComplete);            // ������ʼʱ�ص�            sequence.OnStart(OnStart);            // ���û�������            sequence.SetEase(Ease.Linear);            sequence.Pause();        }        protected abstract void AddTweenToSequence(Sequence seq);        public override void Play()        {            base.Play();            // ���Ŷ���            //sequence.Rewind();            //sequence.Play();            sequence.Restart();        }        public override void Pause()        {            base.Pause();                   sequence.Pause();        }        public override void CanlePause()        {            base.CanlePause();            sequence.Play();        }        public override void Stop()        {            base.Stop();            sequence.Pause();            //sequence.Complete();//����OnComplete            //sequence.Rewind(); �������ص���һ�� �ᵼ�¶���Ӱ���������� һ���ڻῪʼ��ʱ����        }        public override void Run()
        {
            //base.Run();
            //doTween ���������ڲ��������
        }        public override void Disp()        {            base.Disp();            sequence.Kill();            sequence = null;                    }    }        public abstract class Base_CurveTween    {        private AnimationCurve moveCurve = AnimationCurve.Linear(0, 0, 1, 1);        public bool IsPlay;        public bool IsPause;        public bool IsComplete;        public bool IsRun;        public float StartPlayTime;        public float Duration;                    public virtual void Play()        {            IsPlay = true;            IsRun = true;        }        public virtual void Pause()        {            IsPause = true;            IsRun = false;        }        public virtual void CanlePause()        {            IsPause = false;            IsRun = true;        }        public virtual void Stop()        {            ResetState();        }        protected virtual void OnStart()        {        }        protected virtual void OnComplete()        {            IsPlay = false;            IsComplete = true;            IsRun = false;        }        protected virtual void ResetState()        {            IsComplete = false;            IsPause = false;            IsPlay = false;            IsRun = false;            StartPlayTime = 0;            Duration = 0;        }        public virtual void Run()        {            if (!IsPlay || IsComplete || IsPause) return;            float currentTime = TimerUtil.GetGameTime();            // �ӳټ��            if (currentTime < StartPlayTime) return;            // �������            float elapsed = currentTime - StartPlayTime;            float progress = Mathf.Clamp01(elapsed / Duration);            // ʹ��AnimationCurve�������ս���            float curveValue =  moveCurve.Evaluate(progress);            UpdateProgress(curveValue);            // ��ɼ��            if (progress >= 1f)            {                OnComplete();            }        }        protected float GetMoveCurveToTime(float elapsed)        {            float progress = Mathf.Clamp01(elapsed / Duration);            // ʹ��AnimationCurve�������ս���            float curveValue = moveCurve.Evaluate(progress);            return curveValue;        }        protected virtual void UpdateProgress(float curveValue)        {        }        public virtual void Disp()        {            ResetState();        }    }}